import csv
import io
import re
from decimal import Decimal, InvalidOperation, getcontext

getcontext().prec = 80
doc_id = "a127715fdfdb4760e784aa1ce0cfaf40"
raw = documents[doc_id]

if isinstance(raw, dict):
    for key in ("records", "data", "rows"):
        if key in raw:
            raw = raw[key]
            break

header = []
records = []

if isinstance(raw, str):
    reader = csv.DictReader(io.StringIO(raw))
    header = [str(c).strip() for c in (reader.fieldnames or [])]
    for row in reader:
        if all(v is None or str(v).strip() == "" for v in row.values()):
            continue
        records.append((reader.line_num, row))
elif isinstance(raw, list):
    if raw and all(isinstance(row, dict) for row in raw):
        seen = []
        for row in raw:
            for key in row.keys():
                if key not in seen:
                    seen.append(key)
        header = [str(c).strip() for c in seen]
        for index, row in enumerate(raw, start=2):
            if all(v is None or str(v).strip() == "" for v in row.values()):
                continue
            records.append((index, row))
    elif raw and all(isinstance(row, (list, tuple)) for row in raw):
        header = [str(c).strip() for c in raw[0]]
        for index, row in enumerate(raw[1:], start=2):
            mapped = dict(zip(header, row))
            if all(v is None or str(v).strip() == "" for v in mapped.values()):
                continue
            records.append((index, mapped))
else:
    raise ValueError(f"Unsupported CSV document shape: {type(raw).__name__}")

if "amount" not in header:
    result = [{
        "status": "missing_amount_column",
        "total_amount": None,
        "average_amount": None,
        "record_count": None,
        "max_amount": None,
        "error_row": None,
        "error_value": None
    }]
else:
    number_pattern = re.compile(r"^[+-]?(?:\d+(?:\.\d*)?|\.\d+)$")
    values = []
    invalid = None
    for row_number, row in records:
        raw_value = row.get("amount")
        text = "" if raw_value is None else str(raw_value).strip()
        if text == "":
            invalid = (row_number, raw_value, "empty_amount")
            break
        if not number_pattern.fullmatch(text):
            invalid = (row_number, raw_value, "invalid_amount")
            break
        try:
            amount = Decimal(text)
        except InvalidOperation:
            invalid = (row_number, raw_value, "invalid_amount")
            break
        if not amount.is_finite():
            invalid = (row_number, raw_value, "invalid_amount")
            break
        values.append(amount)

    if invalid is not None:
        result = [{
            "status": invalid[2],
            "total_amount": None,
            "average_amount": None,
            "record_count": None,
            "max_amount": None,
            "error_row": invalid[0],
            "error_value": invalid[1]
        }]
    elif not values:
        result = [{
            "status": "no_data_rows",
            "total_amount": None,
            "average_amount": None,
            "record_count": 0,
            "max_amount": None,
            "error_row": None,
            "error_value": None
        }]
    else:
        total = sum(values, Decimal("0"))
        max_amount = max(values)
        average = total / Decimal(len(values))
        result = [{
            "status": "valid",
            "total_amount": str(total),
            "average_amount": str(average),
            "record_count": len(values),
            "max_amount": str(max_amount),
            "error_row": None,
            "error_value": None
        }]

